function speedSamples(samples, sr, rate){
  if(rate==null)rate=1; if(rate<=0)rate=0.25; else if(rate>4)rate=4;
  var N=samples.length; var M=Math.max(1, Math.round(N/rate));
  var out=new Float32Array(M);
  for(var i=0;i<M;i++){ var pos=i*rate; var i0=Math.floor(pos); var i1=Math.min(N-1,i0+1); var f=pos-i0; out[i]=samples[i0]*(1-f)+samples[i1]*f; }
  return out;
}

var EXPORTS={speedSamples:speedSamples};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.AudioSpeedForgePure = EXPORTS; }
